<article class="support-message support-message--<?= e($item['sender_role']) ?>" data-message-id="<?= e($item['id']) ?>"><header><strong><?= $item['sender_role']==='staff'?'تیم منتوریس':'پیام عضو' ?></strong><time data-support-utc="<?= e($item['created_at']) ?>"><?= e(\App\Repositories\SupportRepository::dateLabel($item['created_at'])) ?></time></header><p><?= e($item['body']) ?></p><?php foreach($item['attachments'] as $file): ?><div class="support-message__file"><?php if(in_array($file['media_kind'],['audio','voice'],true)): ?><audio controls preload="none" src="/support/attachments/<?= e($file['id']) ?>"></audio><?php endif; ?><a href="/support/attachments/<?= e($file['id']) ?>"><?= icon('file') ?> <?= e($file['filename']) ?></a></div><?php endforeach; ?></article>
